const PROVIDERS: Record<string, ProviderMeta> = {
  webauthn: { label: 'Passkey', icon: <PasskeyIcon />, enabledKey: 'auth_webauthn_enabled' },
  google: { label: 'Google', icon: <GoogleIcon />, enabledKey: 'auth_google_enabled' },
  apple: { label: 'Apple', icon: <AppleIcon />, enabledKey: 'auth_apple_enabled' },
  solana: { label: 'Solana', icon: <SolanaIcon />, enabledKey: 'auth_solana_enabled' },
};

const DEFAULT_ORDER = ['webauthn', 'google', 'apple', 'solana'];

const PREVIEW_LABELS: Record<string, string> = {
  webauthn: 'Continue with Passkey',
  google: 'Continue with Google',
  apple: 'Continue with Apple',
  solana: 'Continue with Solana',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Read whether a provider is enabled from the flattened settings. */
function isProviderEnabled(
  settings: Record<string, { key: string; value: string }[]>,
  enabledKey: string,
): boolean {
  for (const group of Object.values(settings)) {
    const found = group.find((s) => s.key === enabledKey);
    if (found) return found.value === 'true';
  }
  return true; // default enabled when setting is absent
}

/** Read current order from settings map, falling back to default. */
function readOrder(settings: Record<string, { key: string; value: string }[]>): string[] {
  for (const group of Object.values(settings)) {
    const found = group.find((s) => s.key === 'ui_social_button_order');
    if (found && found.value) return found.value.split(',').map((s) => s.trim());
  }
  return DEFAULT_ORDER;
}

// ---------------------------------------------------------------------------
// Grab-handle icon
// ---------------------------------------------------------------------------

function GrabHandle() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" style={{ opacity: 0.4 }}>
      <circle cx="5" cy="3" r="1.5" />
      <circle cx="11" cy="3" r="1.5" />
      <circle cx="5" cy="8" r="1.5" />
      <circle cx="11" cy="8" r="1.5" />
      <circle cx="5" cy="13" r="1.5" />
      <circle cx="11" cy="13" r="1.5" />
    </svg>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function SocialButtonOrderSettings({ settings, handleChange }: SocialButtonOrderSettingsProps) {
  const [order, setOrder] = useState<string[]>(() => readOrder(settings));
  const dragIdx = useRef<number | null>(null);
  const [dragOverIdx, setDragOverIdx] = useState<number | null>(null);

  const persist = useCallback(
    (newOrder: string[]) => {
      setOrder(newOrder);
      handleChange('ui_social_button_order', newOrder.join(','));
    },
    [handleChange],
  );

  const onDragStart = useCallback((idx: number) => {
    dragIdx.current = idx;
  }, []);

  const onDragOver = useCallback((e: React.DragEvent, idx: number) => {
    e.preventDefault();
    setDragOverIdx(idx);
  }, []);

  const onDrop = useCallback(
    (targetIdx: number) => {
      const fromIdx = dragIdx.current;
      if (fromIdx === null || fromIdx === targetIdx) {
        setDragOverIdx(null);
        return;
      }
      const next = [...order];
      const [moved] = next.splice(fromIdx, 1);
      next.splice(targetIdx, 0, moved);
      persist(next);
      dragIdx.current = null;
      setDragOverIdx(null);
    },
    [order, persist],
  );

  const onDragEnd = useCallback(() => {
    dragIdx.current = null;
    setDragOverIdx(null);
  }, []);

  return (
    <div className="cedros-system-settings">
      <div className="cedros-settings-page-header">
        <div className="cedros-settings-page-header-content">
          <h2 className="cedros-settings-page-title">Button Order</h2>
          <p className="cedros-settings-page-description">
            Drag to reorder the social login buttons on your sign-in form.
          </p>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '2rem', flexWrap: 'wrap' }}>
        {/* Left: Reorder list */}
        <div style={{ flex: '1 1 260px', minWidth: 260 }}>
          <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            {order.map((id, idx) => {
              const meta = PROVIDERS[id];
              if (!meta) return null;
              const enabled = isProviderEnabled(settings, meta.enabledKey);
              const isDragOver = dragOverIdx === idx;
              return (
                <li
                  key={id}
                  draggable
                  onDragStart={() => onDragStart(idx)}
                  onDragOver={(e) => onDragOver(e, idx)}
                  onDrop={() => onDrop(idx)}
                  onDragEnd={onDragEnd}
                  className="cedros-btn-order-item"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.75rem',
                    padding: '0.625rem 0.75rem',
                    borderRadius: 'var(--cedros-radius, 0.5rem)',
                    border: isDragOver
                      ? '2px solid var(--cedros-primary, #6366f1)'
                      : '1px solid var(--cedros-border, #e5e7eb)',
                    background: 'var(--cedros-background, #fff)',
                    cursor: 'grab',
                    opacity: enabled ? 1 : 0.5,
                    transition: 'border-color 0.15s',
                  }}
                >
                  <GrabHandle />
                  <span className="cedros-button-icon" style={{ display: 'flex', alignItems: 'center' }}>
                    {meta.icon}
                  </span>
                  <span style={{ flex: 1, fontWeight: 500, fontSize: '0.875rem' }}>{meta.label}</span>
                  <span
                    style={{
                      fontSize: '0.7rem',
                      padding: '0.125rem 0.5rem',
                      borderRadius: '9999px',
                      background: enabled
                        ? 'var(--cedros-primary, #6366f1)'
                        : 'var(--cedros-muted, #f3f4f6)',
                      color: enabled
                        ? 'var(--cedros-primary-foreground, #fff)'
                        : 'var(--cedros-muted-foreground, #6b7280)',
                    }}
                  >
                    {enabled ? 'Enabled' : 'Disabled'}
                  </span>
                </li>
              );
            })}
          </ul>
        </div>

        {/* Right: Live preview */}
        <div style={{ flex: '1 1 280px', minWidth: 280 }}>
          <p style={{ fontSize: '0.75rem', color: 'var(--cedros-muted-foreground, #6b7280)', margin: '0 0 0.75rem' }}>
            This is how your login form buttons will appear:
          </p>
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '0.5rem',
              padding: '1.25rem',
              borderRadius: 'var(--cedros-radius, 0.5rem)',
              border: '1px solid var(--cedros-border, #e5e7eb)',
              background: 'var(--cedros-background, #fff)',
            }}
          >
            {order.map((id) => {
              const meta = PROVIDERS[id];
              if (!meta) return null;
              const enabled = isProviderEnabled(settings, meta.enabledKey);
              if (!enabled) return null;
              return (
                <button
                  key={id}
                  type="button"
                  className="cedros-button cedros-button-social"
                  style={{ pointerEvents: 'none', width: '100%' }}
                  tabIndex={-1}
                >
                  <span className="cedros-button-icon">{meta.icon}</span>
                  {PREVIEW_LABELS[id]}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
